import{_ as e,C as s,o,c as r,j as i,E as t,a as d,a3 as n}from"./chunks/framework.C6R8kWFE.js";const q=JSON.parse(`{"title":"1-hafta","description":"","frontmatter":{"title":"1-hafta","layout":"doc","sidebar":false,"aside":false,"outline":false,"kind":"hafta","hafta":{"sinf":{"name":"10-sinf (DevOps)","link":"/10-sinf-devops/"},"n":1,"bob":"I-bob · Operatsion tizimlar (Linux)","lessons":[{"g":1,"title":"Linux terminal va asosiy buyruqlar: FHS va fayllar tizimi bilan ishlash","lead":"Linux terminali — DevOps muhandisining eng asosiy quroli: serverlarni boshqarish, fayllar daraxti (FHS) bo'ylab chaqqon harakatlanish va tizimni avtomatlashtirishning poydevori.","link":"/10-sinf-devops/hafta-01/dars-1","slide":"/slaydlar/10-sinf-devops/hafta-01/dars-1.html","test":"/slaydlar/10-sinf-devops/hafta-01/dars-1-test.html"},{"g":2,"title":"Fayl ruxsatlari tizimi va matn tahrirlash vositalari (Nano, Vim)","lead":"Linux xavfsizligining tayanchi bo'lgan ruxsatlar tizimi (ugo/rwx) va server ma'murlari quroli bo'lgan matn muharrirlari (Nano va Vim) sirlari.","link":"/10-sinf-devops/hafta-01/dars-2","slide":"/slaydlar/10-sinf-devops/hafta-01/dars-2.html","test":"/slaydlar/10-sinf-devops/hafta-01/dars-2-test.html"},{"g":3,"title":"Shell muhiti, tizim o'zgaruvchilari va I/O yo'naltirish (Redirection)","lead":"Linux Shell qudrati: tizim o'zgaruvchilari (PATH, export), .bashrc sozlamalari hamda ma'lumot oqimlari (I/O Redirection va quvurlar) yordamida buyruqlarni zanjirga ulash.","link":"/10-sinf-devops/hafta-01/dars-3","slide":"/slaydlar/10-sinf-devops/hafta-01/dars-3.html","test":"/slaydlar/10-sinf-devops/hafta-01/dars-3-test.html"}],"test":"/slaydlar/10-sinf-devops/hafta-01/hafta-test.html"}},"headers":[],"relativePath":"10-sinf-devops/hafta-01/index.md","filePath":"10-sinf-devops/hafta-01/index.md"}`),c={name:"10-sinf-devops/hafta-01/index.md"},h={class:"blk"},u={id:"uyga-vazifa",tabindex:"-1"};function v(g,a,m,f,p,y){const l=s("Icon");return o(),r("div",null,[i("div",h,[i("h2",u,[t(l,{name:"house"}),a[0]||(a[0]=d(" Uyga vazifa ",-1)),a[1]||(a[1]=i("a",{class:"header-anchor",href:"#uyga-vazifa","aria-label":'Permalink to "<Icon name="house" /> Uyga vazifa"'},"​",-1))]),a[2]||(a[2]=n('<p>1-haftada Linux operatsion tizimi, terminal asoslari, FHS kataloglar ierarxiyasi, fayl ruxsatlari (chmod/chown), matn muharrirlari (Nano, Vim) hamda Shell muhiti va I/O yo&#39;naltirish mavzulari o&#39;rganildi. Quyidagi topshiriqlar o&#39;tilgan bilimlarni mustahkamlashga qaratilgan.</p><hr><h3 id="_1-dars-vazifasi-linux-fayl-tizimi-va-navigatsiya" tabindex="-1">1-dars vazifasi: Linux fayl tizimi va navigatsiya <a class="header-anchor" href="#_1-dars-vazifasi-linux-fayl-tizimi-va-navigatsiya" aria-label="Permalink to &quot;1-dars vazifasi: Linux fayl tizimi va navigatsiya&quot;">​</a></h3><ol><li>O&#39;z kompyuteringizdagi Linux terminalida (yoki WSL/VirtualBox Ubuntu muhitida) uy katalogingizda <code>devops_lab</code> nomli asosiy papka oching.</li><li><code>mkdir -p</code> yordamida uning ichida <code>projects/backend</code>, <code>projects/frontend</code>, <code>configs</code> va <code>logs</code> papkalarini bir martada yarating.</li><li>Har bir papka ichida bittadan <code>.txt</code> fayl hosil qiling (<code>touch</code> orqali).</li><li><code>projects/backend</code> ichidagi faylni <code>configs</code> papkasi ichiga boshqa nom bilan nusxalang (<code>cp</code>).</li><li><code>logs</code> papkasidagi faylni <code>projects/frontend</code> ga ko&#39;chiring (<code>mv</code>).</li><li><code>history</code> buyrug&#39;i orqali bajargan barcha amallaringiz ro&#39;yxatini daftaringizga qayd eting. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h3 id="_2-dars-vazifasi-ruxsatlar-va-vim-bilan-ishlash" tabindex="-1">2-dars vazifasi: Ruxsatlar va Vim bilan ishlash <a class="header-anchor" href="#_2-dars-vazifasi-ruxsatlar-va-vim-bilan-ishlash" aria-label="Permalink to &quot;2-dars vazifasi: Ruxsatlar va Vim bilan ishlash&quot;">​</a></h3><ol><li><code>devops_lab</code> papkasi ichida <code>start_server.sh</code> va <code>secret.env</code> nomli ikkita fayl yarating.</li><li><code>nano</code> yoki <code>vim</code> yordamida <code>start_server.sh</code> ichiga quyidagi qatorni yozing:<div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes light-plus dark-plus vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#795E26;--shiki-dark:#DCDCAA;">echo</span><span style="--shiki-light:#A31515;--shiki-dark:#CE9178;"> &quot;Server 8080-portda muvaffaqiyatli ishga tushdi!&quot;</span></span></code></pre></div></li><li><code>secret.env</code> ichiga esa <code>DB_PASSWORD=&quot;SuperSecret123&quot;</code> qatorini kiriting.</li><li><code>chmod</code> orqali quyidagi qat&#39;iy ruxsatlarni o&#39;rnating: <ul><li><code>start_server.sh</code> fayliga: <code>755</code> (egasi to&#39;liq, guruh va boshqalar faqat o&#39;qish va bajarish).</li><li><code>secret.env</code> fayliga: <code>600</code> (faqat egasi o&#39;qish va yozish, qolgan barcha toifalarga mutlaqo taqiqlash).</li></ul></li><li><code>./start_server.sh</code> buyrug&#39;i bilan skriptingizni ishga tushiring va natijani ko&#39;ring.</li><li><code>ls -l</code> buyrug&#39;i natijasini skrinshot qilib yoki daftaringizga ko&#39;chirib yozing. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr><h3 id="_3-dars-vazifasi-shell-muhiti-aliaslar-va-quvurlar" tabindex="-1">3-dars vazifasi: Shell muhiti, Aliaslar va Quvurlar <a class="header-anchor" href="#_3-dars-vazifasi-shell-muhiti-aliaslar-va-quvurlar" aria-label="Permalink to &quot;3-dars vazifasi: Shell muhiti, Aliaslar va Quvurlar&quot;">​</a></h3><ol><li><code>~/.bashrc</code> faylini <code>vim</code> yoki <code>nano</code> bilan oching.</li><li>Faylning eng oxiriga o&#39;tib, quyidagi sozlamalarni qo&#39;shing: <ul><li><code>export MY_ROLE=&quot;DevOps Engineer&quot;</code></li><li><code>alias dlab=&#39;cd ~/devops_lab &amp;&amp; pwd &amp;&amp; ls -la&#39;</code></li><li><code>alias update_sys=&#39;sudo apt update&#39;</code></li></ul></li><li>Faylni saqlang va <code>source ~/.bashrc</code> buyrug&#39;i orqali o&#39;zgarishlarni qo&#39;llang.</li><li>Terminalda <code>echo $MY_ROLE</code> deb yozib o&#39;zgaruvchi ishlaganini, so&#39;ngra <code>dlab</code> deb yozib yangi alias bir zumda sizni laboratoriya papkangizga olib borganini tekshiring.</li><li><code>/etc</code> katalogidagi barcha fayllar ro&#39;yxatini <code>ls /etc | wc -l</code> quvuri orqali sanang va chiqqan raqamni yozib qo&#39;ying. <em>(Kutiladigan vaqt: 25 daqiqa)</em></li></ol><hr>',11))])])}const z=e(c,[["render",v]]);export{q as __pageData,z as default};
